import time
from functools import wraps

def timing(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f'Took {end-start:.4f}s')
        return result
    return wrapper

@timing
def slow_func():
    time.sleep(0.1)
    return 'Done'

print(slow_func())
